void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord.xy * 2.0 - iResolution.xy) * 0.8 / iResolution.y;    

    float t = atan(uv.y * cos(iTime), uv.x * sin(iTime));   
    float d = sin(length(uv) - t + cos(iTime) * 4.5);   

    fragColor = vec4(0.5 + d / fwidth(d));
}
